43	public abstract class AbstractServer implements AutoCloseable, MetricsProducer, Runnable {
44	
45	  private final ServerContext context;
46	  protected final String applicationName;
47	  private final String hostname;
48	  private final String resourceGroup;
49	
50	  private final ProcessMetrics processMetrics;
51	
52	  protected AbstractServer(String appName, ConfigOpts opts, String[] args) {
53	    this.applicationName = appName;
54	    opts.parseArgs(appName, args);
55	    var siteConfig = opts.getSiteConfiguration();
56	    this.hostname = siteConfig.get(Property.GENERAL_PROCESS_BIND_ADDRESS);
57	    this.resourceGroup = getResourceGroupPropertyValue(siteConfig);
58	    SecurityUtil.serverLogin(siteConfig);
59	    context = new ServerContext(siteConfig);
60	    Logger log = LoggerFactory.getLogger(getClass());
61	    log.info("Version " + Constants.VERSION);
62	    log.info("Instance " + context.getInstanceID());
63	    context.init(appName);
64	    ClassLoaderUtil.initContextFactory(context.getConfiguration());
65	    TraceUtil.initializeTracer(context.getConfiguration());
66	    if (context.getSaslParams() != null) {
67	      // Server-side "client" check to make sure we're logged in as a user we expect to be
68	      context.enforceKerberosLogin();
69	    }
70	    final LowMemoryDetector lmd = context.getLowMemoryDetector();
71	    ScheduledFuture<?> future = context.getScheduledExecutor().scheduleWithFixedDelay(
72	        () -> lmd.logGCInfo(context.getConfiguration()), 0,
73	        lmd.getIntervalMillis(context.getConfiguration()), TimeUnit.MILLISECONDS);
74	    ThreadPools.watchNonCriticalScheduledTask(future);
75	    processMetrics = new ProcessMetrics(context);
76	  }
77	
78	  protected String getResourceGroupPropertyValue(SiteConfiguration conf) {
79	    return Constants.DEFAULT_RESOURCE_GROUP_NAME;
80	  }
81	
82	  public String getResourceGroup() {
83	    return resourceGroup;
84	  }
85	
86	  /**
87	   * Run this server in a main thread
88	   */
89	  public void runServer() throws Exception {
90	    final AtomicReference<Throwable> err = new AtomicReference<>();
91	    Thread service = new Thread(TraceUtil.wrap(this), applicationName);
92	    service.setUncaughtExceptionHandler((thread, exception) -> err.set(exception));
93	    service.start();
94	    service.join();
95	    Throwable thrown = err.get();
96	    if (thrown != null) {
97	      if (thrown instanceof Error) {
98	        throw (Error) thrown;
99	      }
100	      if (thrown instanceof Exception) {
101	        throw (Exception) thrown;
102	      }
103	      throw new IllegalStateException("Weird throwable type thrown", thrown);
104	    }
105	  }
106	
107	  /**
108	   * Called
109	   */
110	  @Override
111	  public void registerMetrics(MeterRegistry registry) {
112	    // makes mocking subclasses easier
113	    if (processMetrics != null) {
114	      processMetrics.registerMetrics(registry);
115	    }
116	    getContext().setMeterRegistry(registry);
117	  }
118	
119	  public String getHostname() {
120	    return hostname;
121	  }
122	
123	  public ServerContext getContext() {
124	    return context;
125	  }
126	
127	  public AccumuloConfiguration getConfiguration() {
128	    return getContext().getConfiguration();
129	  }
130	
131	  @Override
132	  public void close() {
133	    MetricsUtil.close();
134	  }
135	
136	}
